begin;

with guide_data as (
  select *
  from jsonb_to_recordset($guides$
[{"slug":"goblet-squat","start":"Stand with the feet about shoulder width, toes slightly turned out and a dumbbell or kettlebell held close to the chest.","finish":"Descend to the deepest controlled squat that keeps the heels planted, knees tracking with the toes and the torso upright.","setup":["Hold the weight vertically at chest height with the elbows pointing down.","Set the feet at a comfortable squat width and create tripod pressure through heel, base of big toe and base of little toe.","Brace the abdomen and keep the ribcage stacked over the pelvis before beginning."],"execution":["Bend the knees and hips together while sitting between the legs rather than folding forward.","Lower under control until mobility or trunk position limits the range.","Drive through the full foot and extend the hips and knees to return to standing."],"cues":["Keep the weight close enough that it feels like part of the torso.","Let the knees follow the direction of the toes.","Stay tall and push the floor away on the ascent."],"mistakes":["Allowing the heels or foot arches to lift.","Letting the knees collapse inward.","Holding the weight away from the body and losing torso position."],"safety":["Use a load that can be lifted safely into position without straining the wrists or lower back.","Reduce depth or elevate the heels slightly if mobility limits cause the pelvis or spine to lose control."],"breathing":"Inhale and brace before descending; keep pressure through the bottom and exhale as you pass the hardest part of the ascent.","tempo":"Lower in 2–3 seconds, pause briefly at the bottom and stand in 1–2 seconds.","muscles":["Quadriceps","Gluteus maximus","Adductors","Core"]},{"slug":"walking-lunge","start":"Stand tall with the feet under the hips, trunk braced and dumbbells held at the sides when resistance is used.","finish":"Step into a split stance and lower until both knees are comfortably bent while the front heel remains planted and the torso stays controlled.","setup":["Clear enough space for several controlled steps and choose a load that does not disturb balance.","Stand tall with the ribs stacked over the pelvis and the shoulders relaxed.","Keep the feet approximately hip width rather than walking on a tightrope."],"execution":["Step forward far enough that the front foot can stay fully planted.","Lower both knees under control while keeping the front knee aligned with the toes.","Push through the front foot, bring the body forward and continue into the next repetition."],"cues":["Step on railroad tracks, not a balance beam.","Keep the front heel heavy and the torso tall.","Push the ground behind you as you move into the next step."],"mistakes":["Taking steps that are too short and driving the front knee forward without control.","Letting the front knee collapse inward.","Slamming the back knee into the floor or rushing between steps."],"safety":["Use bodyweight or stationary split squats first if balance is limited.","Stop or shorten the range if knee pain increases, and keep enough room to avoid obstacles during the set."],"breathing":"Inhale as you step and lower; exhale as you push through the front leg and rise.","tempo":"Use about 2 seconds down, a brief controlled bottom position and a smooth transition into the next step.","muscles":["Quadriceps","Gluteus maximus","Hamstrings","Adductors","Core"]},{"slug":"incline-dumbbell-press","start":"Lie on a moderately inclined bench with the feet planted, shoulder blades supported and dumbbells held beside the upper chest.","finish":"Press the dumbbells above the upper chest until the arms are extended without the shoulders shrugging or the weights colliding.","setup":["Set the bench to a moderate incline and confirm it is locked securely.","Bring the dumbbells to the thighs, sit back and guide them into position without twisting.","Plant the feet and draw the shoulder blades down and together against the bench."],"execution":["Lower the dumbbells beside the upper chest with the elbows at a comfortable angle below shoulder level.","Pause at a pain-free depth while keeping wrists stacked over forearms.","Press upward and slightly inward until the arms are extended and the upper back remains anchored."],"cues":["Keep the chest tall and shoulder blades heavy on the bench.","Stack the wrists over the elbows throughout the repetition.","Press toward the ceiling rather than banging the dumbbells together."],"mistakes":["Flaring the elbows directly sideways.","Letting the shoulders roll forward at the bottom.","Using momentum to kick or drop the dumbbells into position."],"safety":["Use a spotter for heavy sets and choose a load that can be returned safely to the thighs.","Reduce the incline, grip width or depth if shoulder discomfort appears."],"breathing":"Inhale while lowering; maintain tension at the bottom and exhale as the dumbbells pass the sticking point.","tempo":"Lower in 2–3 seconds, pause briefly and press in 1–2 seconds.","muscles":["Upper pectoralis major","Anterior deltoids","Triceps"]},{"slug":"push-up","start":"Place the hands slightly wider than the shoulders and support the body in a straight high-plank line from head to heels.","finish":"Lower the chest toward the floor with elbows controlled, then press back to full arm extension without losing trunk position.","setup":["Place the hands on the floor or an elevated surface at a level that allows full control.","Spread the fingers, grip the surface and stack the shoulders over the wrists.","Brace the abdomen and squeeze the glutes so the pelvis remains level."],"execution":["Bend the elbows and lower the chest while keeping the body moving as one unit.","Reach a depth that keeps the shoulders comfortable and the forearms stable.","Press the surface away until the elbows extend and the shoulder blades move naturally around the ribs."],"cues":["Keep a straight line from ears to ankles.","Aim the chest between the hands rather than dropping the head.","Push the floor away at the top."],"mistakes":["Allowing the hips to sag or rise before the chest.","Flaring the elbows directly sideways.","Shortening the range because the chosen variation is too difficult."],"safety":["Elevate the hands on a bench or rack if full floor repetitions cannot be controlled.","Use neutral-grip handles or an elevated surface if wrist extension is uncomfortable."],"breathing":"Inhale during the lowering phase and exhale while pressing away from the floor.","tempo":"Lower in 2 seconds, pause briefly near the bottom and press in 1–2 seconds.","muscles":["Pectoralis major","Triceps","Anterior deltoids","Core","Serratus anterior"]},{"slug":"lat-pulldown","start":"Sit with the thighs secured, torso tall and arms extended overhead while holding the bar with a comfortable grip.","finish":"Pull the bar toward the upper chest by driving the elbows down while keeping the torso stable and the neck neutral.","setup":["Adjust the thigh pad so the body remains securely seated without excessive pressure.","Choose a grip that permits comfortable shoulder motion and wrap the thumbs securely.","Sit tall, brace the trunk and set the shoulders gently away from the ears."],"execution":["Initiate by drawing the shoulder blades down, then bend the elbows toward the sides of the torso.","Pull the bar toward the upper chest without leaning far backward.","Return the bar slowly until the arms extend and the shoulders reach a controlled overhead position."],"cues":["Drive the elbows toward the back pockets.","Keep the chest tall without turning the movement into a row.","Let the shoulders rise only under control at the top."],"mistakes":["Swinging the torso to move excessive weight.","Pulling the bar behind the neck.","Shrugging throughout the pull or shortening the return."],"safety":["Do not force a grip width or range that causes shoulder pain.","Keep the pin fully inserted and release the bar only after the weight stack is controlled."],"breathing":"Exhale as the bar moves down and inhale during the controlled overhead return.","tempo":"Pull in 1–2 seconds, pause briefly near the chest and return in 2–3 seconds.","muscles":["Latissimus dorsi","Biceps","Rhomboids","Lower trapezius"]},{"slug":"seated-cable-row","start":"Sit with the feet braced, knees softly bent, spine tall and arms extended toward the low pulley.","finish":"Pull the handle toward the lower ribs with the elbows moving behind the torso while the trunk remains stable.","setup":["Select an attachment and load that allow a full controlled range.","Place the feet securely on the platform and sit with the ribs stacked over the pelvis.","Reach the arms forward without collapsing the lower back or shrugging excessively."],"execution":["Initiate the row by drawing the shoulder blades back and driving the elbows toward the hips.","Bring the handle to the lower ribs without leaning backward.","Extend the arms slowly and allow a controlled forward reach while maintaining spinal position."],"cues":["Stay tall and row the elbows behind you.","Pull toward the lower ribs, not the neck.","Keep the cable moving in a straight quiet line."],"mistakes":["Using repeated torso rocking to move the load.","Rounding the lower back at full reach.","Shrugging the shoulders or letting the elbows flare widely."],"safety":["Keep fingers clear of the weight stack and attachment connection.","Use a chest-supported alternative if lower-back fatigue prevents a stable seated position."],"breathing":"Exhale during the pull and inhale as the arms return forward.","tempo":"Pull in 1–2 seconds, pause briefly at the torso and return in 2–3 seconds.","muscles":["Latissimus dorsi","Rhomboids","Middle trapezius","Posterior deltoids","Biceps"]},{"slug":"single-arm-dumbbell-row","start":"Support one hand and knee on a bench, keep the spine neutral and let the working arm hang toward the floor.","finish":"Pull the dumbbell toward the hip with the elbow close to the torso while keeping the shoulders and pelvis level.","setup":["Place the supporting hand and knee securely on a stable bench.","Set the non-supported foot firmly on the floor and brace the abdomen.","Allow the working shoulder to reach slightly without rotating the trunk."],"execution":["Drive the elbow toward the hip while keeping the dumbbell close to the body.","Pause when the upper arm reaches the torso without twisting the chest upward.","Lower the dumbbell slowly until the arm extends and the shoulder reaches under control."],"cues":["Keep the hips and shoulders square to the floor.","Row toward the pocket, not the armpit.","Let the arm lengthen without losing the brace."],"mistakes":["Rotating the torso to lift the weight.","Shrugging the working shoulder toward the ear.","Pulling too high and turning the movement into shoulder extension."],"safety":["Use a bench height and stance that do not strain the supporting wrist or lower back.","Keep the dumbbell clear of the bench and lower it to the floor with control after the set."],"breathing":"Exhale as the dumbbell rises and inhale during the controlled lowering phase.","tempo":"Pull in 1–2 seconds, pause briefly and lower in 2–3 seconds.","muscles":["Latissimus dorsi","Rhomboids","Posterior deltoids","Biceps","Core"]},{"slug":"romanian-deadlift","start":"Stand tall with the load held against the thighs, feet about hip width, knees softly bent and trunk braced.","finish":"Hinge until the hamstrings are strongly loaded and the weight reaches a controlled depth while the spine remains neutral.","setup":["Use a secure grip and position the bar or dumbbells close to the front of the thighs.","Set the feet under the hips and unlock the knees slightly.","Brace the abdomen, set the shoulders and prepare to move the hips backward."],"execution":["Push the hips back while the weight slides close to the legs.","Continue until hamstring tension or trunk position limits the range.","Drive the hips forward and stand tall without leaning backward."],"cues":["Close the car door with the hips.","Keep the weight close enough to brush the legs.","Maintain soft knees while the hips do most of the movement."],"mistakes":["Turning the movement into a squat by bending the knees excessively.","Rounding the lower back to reach a deeper position.","Letting the weight drift away from the body."],"safety":["Choose a range based on hamstring mobility rather than trying to reach the floor.","Stop if sharp back pain or loss of trunk control occurs and reduce the load before continuing."],"breathing":"Inhale and brace before hinging; keep the brace through the bottom and exhale as the hips extend.","tempo":"Lower in 3 seconds, pause briefly in the loaded position and stand in 1–2 seconds.","muscles":["Hamstrings","Gluteus maximus","Adductors","Spinal erectors","Core"]},{"slug":"glute-bridge","start":"Lie on the back with the knees bent, feet planted near the hips and arms resting securely on the floor.","finish":"Lift the hips until the trunk and thighs form a straight line while the ribs stay controlled and the glutes remain engaged.","setup":["Place the feet about hip width with the heels close enough to create comfortable knee angles.","Set the head, shoulders and upper back on the floor and brace the abdomen.","Keep the knees aligned with the feet before initiating the lift."],"execution":["Drive through the feet and squeeze the glutes to raise the pelvis.","Pause at the top without arching the lower back or flaring the ribs.","Lower the hips slowly until the pelvis approaches the floor."],"cues":["Tuck the belt buckle slightly toward the ribs.","Push through the whole foot and keep the knees apart.","Finish with the glutes, not the lower back."],"mistakes":["Overarching the lumbar spine at the top.","Placing the feet too far away and feeling mostly hamstrings.","Letting the knees collapse inward."],"safety":["Use bodyweight first and keep added resistance padded and centered over the pelvis.","Reduce range if lower-back discomfort appears."],"breathing":"Exhale while lifting and inhale during the controlled lowering phase.","tempo":"Lift in 1–2 seconds, hold the top for 1 second and lower in 2–3 seconds.","muscles":["Gluteus maximus","Hamstrings","Core"]},{"slug":"barbell-hip-thrust","start":"Sit with the upper back against a stable bench, bar padded across the hip crease and feet planted in front of the body.","finish":"Drive the hips upward until the trunk is approximately parallel to the floor and the shins are near vertical.","setup":["Secure the bench so it cannot slide and position its edge below the shoulder blades.","Use a thick pad and center the bar over the hip crease.","Plant the feet about hip width and find a position that produces near-vertical shins at the top."],"execution":["Brace the abdomen and drive through the feet to raise the hips.","Reach full hip extension while keeping the chin slightly tucked and ribs controlled.","Lower the hips under control without allowing the bar to shift."],"cues":["Keep the eyes forward and the chin gently tucked.","Drive the knees outward and squeeze the glutes at the top.","Stop when the hips are extended, not when the back arches."],"mistakes":["Hyperextending the lower back at lockout.","Placing the feet too close or too far from the hips.","Allowing the knees to collapse inward or the bench to move."],"safety":["Secure the bench and use collars on the bar when appropriate.","Use a load that can be rolled or removed safely and stop if pressure from the bar causes numbness or sharp pain."],"breathing":"Inhale and brace at the bottom; exhale as the hips reach full extension.","tempo":"Lift in 1–2 seconds, hold the top for 1 second and lower in 2–3 seconds.","muscles":["Gluteus maximus","Hamstrings","Adductors","Core"]},{"slug":"dead-bug","start":"Lie on the back with arms reaching upward, hips and knees bent to about 90 degrees and the lower back gently supported by abdominal tension.","finish":"Extend one arm and the opposite leg away from the body while keeping the ribs down and the lower back from lifting.","setup":["Lie with the head relaxed and bring the knees above the hips.","Reach the arms toward the ceiling and exhale to bring the ribs into a stacked position.","Create gentle abdominal pressure before moving any limb."],"execution":["Slowly extend the opposite arm and leg until just before the back begins to arch.","Pause while maintaining abdominal tension and controlled breathing.","Return to the start and repeat on the other side."],"cues":["Keep the belt line heavy on the floor.","Move only as far as the trunk can stay still.","Reach long through the heel and fingertips."],"mistakes":["Allowing the lower back to lift as the limbs extend.","Moving too quickly and losing coordination.","Holding the breath throughout the repetition."],"safety":["Shorten the lever by bending the knee or moving only one limb if trunk control is limited.","Stop if the exercise increases back pain despite reducing the range."],"breathing":"Exhale as the arm and leg extend, then inhale as they return while maintaining abdominal tension.","tempo":"Extend for 2–3 seconds, pause briefly and return in about 2 seconds.","muscles":["Transverse abdominis","Rectus abdominis","Obliques","Hip flexors"]},{"slug":"leg-press","start":"Sit with the back and pelvis supported, feet placed securely on the platform and knees bent within a comfortable range.","finish":"Press the platform away until the knees are extended but not aggressively locked while the pelvis stays against the pad.","setup":["Adjust the seat so the hips and knees can move through a controlled pain-free range.","Place the feet about shoulder width with the entire foot contacting the platform.","Release the safety handles only after the body is stable and the platform is under control."],"execution":["Lower the platform slowly by bending the knees and hips together.","Stop before the pelvis rolls away from the back pad or the heels lift.","Press through the full feet and extend the legs without snapping the knees straight."],"cues":["Keep the lower back and pelvis heavy against the pad.","Let the knees track in line with the toes.","Drive through the whole foot, not only the toes."],"mistakes":["Lowering so far that the pelvis curls off the pad.","Locking the knees forcefully at the top.","Allowing the knees to collapse inward or the heels to lift."],"safety":["Engage the safety stops before entering or leaving the machine.","Do not place hands or objects near the moving rails or platform."],"breathing":"Inhale while lowering and exhale during the press through the most difficult portion.","tempo":"Lower in 2–3 seconds, pause briefly and press in 1–2 seconds.","muscles":["Quadriceps","Gluteus maximus","Hamstrings","Adductors"]},{"slug":"seated-leg-curl","start":"Sit with the knees aligned to the machine pivot, thighs secured and lower legs resting against the moving pad.","finish":"Curl the heels down and back as far as controlled while keeping the hips and thighs firmly against the seat.","setup":["Adjust the seat and back pad so the knees align with the machine axis.","Position the lower-leg pad above the heels and secure the thigh restraint.","Grip the handles lightly and keep the pelvis against the pad."],"execution":["Curl the lower legs downward and backward by flexing the knees.","Pause briefly at the strongest hamstring contraction.","Return the pad slowly until the knees reach a comfortable extended position."],"cues":["Keep the hips heavy in the seat.","Pull the heels back rather than kicking downward.","Control the final part of the return."],"mistakes":["Lifting the hips to move a heavier load.","Letting the stack slam at the top.","Using a seat position that misaligns the knees with the pivot."],"safety":["Confirm all adjustment pins are fully engaged before starting.","Avoid forcing full extension if it causes pain behind the knee."],"breathing":"Exhale while curling and inhale during the controlled return.","tempo":"Curl in 1–2 seconds, hold for 1 second and return in 2–3 seconds.","muscles":["Hamstrings","Gastrocnemius"]},{"slug":"leg-extension","start":"Sit with the knees aligned to the machine pivot, hips supported and shins positioned behind the lower pad.","finish":"Extend the knees until the legs approach straight without slamming into lockout or lifting the hips.","setup":["Adjust the seat so the knees align with the machine axis.","Set the shin pad above the ankles and secure the back support.","Grip the handles and keep the pelvis and thighs in contact with the seat."],"execution":["Extend the knees smoothly and lift the pad without swinging.","Pause briefly near the top while maintaining control.","Lower the weight slowly until the knees return to a comfortable bent position."],"cues":["Keep the hips down and move only at the knees.","Lift smoothly rather than kicking the pad.","Control the last third of the lowering phase."],"mistakes":["Using momentum and lifting the hips from the seat.","Snapping the knees into a hard lockout.","Letting the weight stack slam between repetitions."],"safety":["Use a load and range that do not aggravate the knees.","Confirm the machine pivot and pad positions before increasing resistance."],"breathing":"Exhale during knee extension and inhale while lowering the weight.","tempo":"Extend in 1–2 seconds, hold briefly and lower in 2–3 seconds.","muscles":["Quadriceps"]},{"slug":"dumbbell-lateral-raise","start":"Stand tall with dumbbells beside the thighs, palms facing inward and elbows softly bent.","finish":"Raise the arms out to the sides until they approach shoulder height while the shoulders remain down and the trunk stays still.","setup":["Choose light resistance that can be controlled without swinging.","Stand with feet about hip width, ribs stacked and shoulders relaxed.","Keep a slight fixed bend in the elbows and wrists neutral."],"execution":["Raise the arms outward in the plane of the shoulders with the elbows leading.","Stop at a comfortable height near shoulder level.","Lower the dumbbells slowly to the sides without losing posture."],"cues":["Lead with the elbows, not the hands.","Keep the shoulders away from the ears.","Move smoothly and stop before momentum begins."],"mistakes":["Swinging the torso or bending the knees to start the weights.","Shrugging the shoulders upward.","Raising far above shoulder height despite losing control."],"safety":["Reduce load or use the cable version if shoulder discomfort appears.","Avoid forcing the thumbs sharply downward or the arms into a painful position."],"breathing":"Exhale as the arms rise and inhale during the controlled lowering phase.","tempo":"Raise in about 2 seconds and lower in 2–3 seconds.","muscles":["Medial deltoids","Anterior deltoids","Upper trapezius"]},{"slug":"standing-calf-raise","start":"Stand with the balls of the feet supported, heels free to move and the body balanced against a stable support or machine.","finish":"Rise onto the toes as high as controlled while keeping the ankles aligned and the knees softly extended.","setup":["Position the balls of the feet securely on the edge of the platform.","Use the handles or shoulder pads only for support, not to pull the body upward.","Align the feet forward or slightly turned out according to comfort."],"execution":["Lower the heels slowly into a comfortable calf stretch.","Press through the balls of the feet and rise as high as possible without rolling the ankles.","Pause briefly at the top, then descend under control."],"cues":["Move straight up and down through the big-toe side of the foot.","Pause at both the stretch and the top.","Keep the ankles from rolling outward."],"mistakes":["Bouncing rapidly through the bottom.","Using a very short range of motion.","Letting the feet slide or the ankles collapse outward."],"safety":["Use a stable support and avoid stepping too far off the platform.","Reduce range if the Achilles tendon or forefoot becomes painful."],"breathing":"Exhale while rising and inhale during the controlled lowering phase.","tempo":"Lower for 2–3 seconds, pause briefly, rise in 1–2 seconds and hold the top for 1 second.","muscles":["Gastrocnemius","Soleus"]},{"slug":"cable-chest-fly","start":"Stand between the cable towers with a staggered stance, arms open and elbows softly bent while the cables remain under tension.","finish":"Sweep the hands together in front of the chest without changing the elbow angle or letting the shoulders roll forward.","setup":["Set both pulleys to the same height and attach matching handles.","Step forward into a stable stance and brace the trunk.","Open the arms only to a range that keeps the shoulders comfortable."],"execution":["Bring the arms forward in a wide hugging arc while keeping a fixed elbow bend.","Pause when the hands meet or nearly meet in front of the chest.","Return slowly until the chest is stretched without the shoulders being pulled backward."],"cues":["Hug a large barrel rather than pressing the handles.","Keep the ribs down and the shoulders away from the ears.","Let the chest move the arms while the elbows stay soft."],"mistakes":["Turning the exercise into a press by bending and straightening the elbows.","Overstretching the shoulders behind the body.","Leaning or rocking to move excessive weight."],"safety":["Check that handles and carabiners are secure before stepping into position.","Use a smaller range or lower pulley height if shoulder irritation occurs."],"breathing":"Exhale as the handles move together and inhale during the controlled opening phase.","tempo":"Close in 1–2 seconds, pause briefly and open in 2–3 seconds.","muscles":["Pectoralis major","Anterior deltoids","Serratus anterior"]},{"slug":"face-pull","start":"Stand facing a cable set near eye level with arms extended, rope held securely and body braced.","finish":"Pull the rope toward the face while separating the hands and moving the elbows back without shrugging.","setup":["Set the pulley near face height and attach a rope.","Step back until the cable is taut and establish a stable stance.","Hold the rope with thumbs pointing behind you or toward the ears."],"execution":["Pull the rope toward the eyes or forehead while the elbows travel outward and back.","Separate the rope ends as the shoulder blades move together.","Return slowly until the arms extend without losing posture."],"cues":["Pull the rope apart as it approaches the face.","Keep the shoulders down and the ribs stacked.","Finish with the hands beside the ears, not at the chest."],"mistakes":["Leaning far backward to move the load.","Shrugging the shoulders during the pull.","Pulling to the chest like a conventional row."],"safety":["Use a load that allows the rope to stop before contacting the face.","Check the attachment and cable before starting and maintain enough distance from the stack."],"breathing":"Exhale during the pull and inhale as the arms extend.","tempo":"Pull in about 2 seconds, pause briefly and return in 2–3 seconds.","muscles":["Posterior deltoids","Rhomboids","Middle trapezius","External rotators"]},{"slug":"triceps-pushdown","start":"Stand facing the cable with the elbows bent and pinned beside the torso, wrists neutral and trunk braced.","finish":"Extend the elbows until the arms are straight while the upper arms and shoulders remain still.","setup":["Attach a rope or bar to a high pulley and select a manageable load.","Stand close enough that the cable remains nearly vertical.","Set the shoulders down and place the elbows beside the ribs."],"execution":["Press the attachment downward by extending only the elbows.","Reach full comfortable extension and briefly contract the triceps.","Allow the elbows to bend slowly until the forearms return near the upper abdomen."],"cues":["Glue the elbows to the sides.","Move the forearms, not the shoulders.","Finish down and slightly apart when using a rope."],"mistakes":["Rocking the torso to move the weight.","Letting the elbows drift forward during the return.","Bending the wrists or shrugging the shoulders."],"safety":["Keep fingers clear of the cable and weight stack.","Reduce load if elbow discomfort or loss of shoulder position occurs."],"breathing":"Exhale during the pushdown and inhale as the attachment returns.","tempo":"Press in 1–2 seconds, pause briefly and return in 2–3 seconds.","muscles":["Triceps brachii"]},{"slug":"overhead-triceps-extension","start":"Hold a dumbbell or cable attachment overhead with the elbows bent and upper arms positioned beside the head.","finish":"Extend the elbows until the arms are straight overhead without arching the lower back or flaring the ribs.","setup":["Choose a dumbbell, rope or handle that can be positioned safely overhead.","Stand or sit tall with the abdomen braced and ribs stacked.","Keep the upper arms close to the head and wrists neutral."],"execution":["Lower the resistance behind the head by bending the elbows.","Stop at a comfortable stretch while the upper arms remain stable.","Extend the elbows to return the resistance overhead without moving the torso."],"cues":["Point the elbows forward and keep them narrow.","Keep the ribs down as the arms extend.","Move at the elbows while the upper arms stay quiet."],"mistakes":["Arching the lower back to finish the repetition.","Allowing the elbows to flare widely.","Using shoulder movement instead of elbow extension."],"safety":["Use a spotter or cable setup when a heavy dumbbell is difficult to position safely.","Reduce range or choose a pushdown variation if overhead shoulder position is uncomfortable."],"breathing":"Inhale while lowering and exhale during elbow extension.","tempo":"Lower in 2–3 seconds, pause briefly and extend in 1–2 seconds.","muscles":["Triceps brachii","Anconeus"]},{"slug":"hammer-curl","start":"Stand tall with dumbbells beside the thighs, palms facing inward and elbows close to the torso.","finish":"Curl the dumbbells upward with the neutral grip maintained while the upper arms remain nearly still.","setup":["Choose dumbbells that allow the full range without torso movement.","Stand with the ribs stacked, shoulders relaxed and wrists neutral.","Keep the elbows beside the body before beginning."],"execution":["Bend the elbows and raise the dumbbells while the palms continue facing each other.","Pause near the top without moving the elbows forward excessively.","Lower the dumbbells slowly until the arms are extended."],"cues":["Keep the thumbs pointing upward.","Pin the elbows near the ribs.","Lower all the way without losing wrist alignment."],"mistakes":["Swinging the torso to start each repetition.","Letting the elbows travel far forward.","Bending the wrists as the dumbbells rise."],"safety":["Reduce load if forearm or elbow discomfort increases.","Keep a clear space so the dumbbells do not strike the thighs or nearby equipment."],"breathing":"Exhale while curling and inhale during the controlled lowering phase.","tempo":"Curl in 1–2 seconds, pause briefly and lower in 2–3 seconds.","muscles":["Brachialis","Brachioradialis","Biceps brachii","Forearms"]},{"slug":"barbell-curl","start":"Stand tall with the bar held near the thighs, palms forward, arms extended and elbows close to the torso.","finish":"Curl the bar toward the upper abdomen or chest while keeping the shoulders and trunk still.","setup":["Choose a straight or EZ bar that feels comfortable on the wrists.","Stand with feet about hip width and brace the abdomen.","Set the elbows slightly in front of or beside the torso and keep the wrists neutral."],"execution":["Curl the bar by bending the elbows without leaning backward.","Pause near the top while maintaining shoulder position.","Lower the bar slowly until the arms reach full comfortable extension."],"cues":["Keep the elbows quiet and the chest still.","Curl the bar smoothly instead of throwing it upward.","Control the bottom position before beginning the next repetition."],"mistakes":["Using hip drive or leaning backward.","Allowing the elbows to drift far forward.","Dropping the bar quickly through the lowering phase."],"safety":["Use an EZ bar or dumbbells if a straight bar irritates the wrists or elbows.","Keep the bar path clear and do not release the bar until it is securely racked or lowered."],"breathing":"Exhale while curling and inhale during the controlled lowering phase.","tempo":"Curl in 1–2 seconds, pause briefly and lower in 2–3 seconds.","muscles":["Biceps brachii","Brachialis","Brachioradialis","Forearms"]},{"slug":"cable-crunch","start":"Kneel facing the cable with the rope held beside the head, hips stable and trunk upright under tension.","finish":"Curl the ribcage toward the pelvis by flexing the spine while the hips remain mostly fixed.","setup":["Attach a rope to a high pulley and kneel far enough away for continuous cable tension.","Hold the rope beside the temples or shoulders without pulling it against the neck.","Set the hips over or slightly behind the knees and brace the abdomen."],"execution":["Exhale and curl the upper trunk downward by bringing the ribs toward the pelvis.","Pause in the contracted position without sitting the hips backward.","Return slowly until the trunk reaches the starting position while maintaining tension."],"cues":["Shorten the distance between the ribs and pelvis.","Keep the hips quiet and let the spine flex.","Use the arms only to hold the rope in place."],"mistakes":["Pulling the rope down mainly with the arms.","Hinging at the hips instead of curling the trunk.","Using momentum and letting the weight stack slam."],"safety":["Use padding under the knees and keep the rope away from the throat.","Reduce load or range if the movement causes neck or lower-back discomfort."],"breathing":"Exhale fully during the downward curl and inhale during the controlled return.","tempo":"Curl in 1–2 seconds, hold briefly and return in 2–3 seconds.","muscles":["Rectus abdominis","Obliques"]}]
$guides$::jsonb) as x(
    slug text,
    start text,
    finish text,
    setup text[],
    execution text[],
    cues text[],
    mistakes text[],
    safety text[],
    breathing text,
    tempo text,
    muscles jsonb
  )
)
insert into public.exercise_technique_guides (
  exercise_id,
  start_position,
  finish_position,
  setup_steps,
  execution_steps,
  coaching_cues,
  common_mistakes,
  safety_notes,
  breathing,
  tempo_guidance,
  muscle_highlights,
  content_source,
  status,
  version,
  is_active
)
select
  e.id,
  d.start,
  d.finish,
  d.setup,
  d.execution,
  d.cues,
  d.mistakes,
  d.safety,
  d.breathing,
  d.tempo,
  d.muscles,
  'editorial',
  'published',
  2,
  true
from guide_data d
join public.exercise_library e on e.slug = d.slug
on conflict (exercise_id) do update
set
  start_position = excluded.start_position,
  finish_position = excluded.finish_position,
  setup_steps = excluded.setup_steps,
  execution_steps = excluded.execution_steps,
  coaching_cues = excluded.coaching_cues,
  common_mistakes = excluded.common_mistakes,
  safety_notes = excluded.safety_notes,
  breathing = excluded.breathing,
  tempo_guidance = excluded.tempo_guidance,
  muscle_highlights = excluded.muscle_highlights,
  content_source = 'editorial',
  status = 'published',
  version = public.exercise_technique_guides.version + 1,
  is_active = true,
  updated_at = now();

do $validation$
declare
  upgraded_guides integer;
  active_exercises integer;
  complete_guides integer;
begin
  select count(*)
  into upgraded_guides
  from public.exercise_library e
  join public.exercise_technique_guides g on g.exercise_id = e.id
  where e.slug in ('goblet-squat','walking-lunge','incline-dumbbell-press','push-up','lat-pulldown','seated-cable-row','single-arm-dumbbell-row','romanian-deadlift','glute-bridge','barbell-hip-thrust','dead-bug','leg-press','seated-leg-curl','leg-extension','dumbbell-lateral-raise','standing-calf-raise','cable-chest-fly','face-pull','triceps-pushdown','overhead-triceps-extension','hammer-curl','barbell-curl','cable-crunch')
    and g.is_active
    and g.status = 'published'
    and g.start_position is not null
    and g.finish_position is not null
    and cardinality(g.setup_steps) >= 3
    and cardinality(g.execution_steps) >= 3
    and cardinality(g.coaching_cues) >= 3
    and cardinality(g.common_mistakes) >= 3
    and cardinality(g.safety_notes) >= 2
    and g.breathing is not null
    and g.tempo_guidance is not null
    and jsonb_array_length(g.muscle_highlights) >= 1;

  if upgraded_guides <> 23 then
    raise exception 'Expected 23 complete upgraded guides, found %', upgraded_guides;
  end if;

  select count(*) into active_exercises
  from public.exercise_library
  where is_active;

  select count(*)
  into complete_guides
  from public.exercise_library e
  join public.exercise_technique_guides g on g.exercise_id = e.id
  where e.is_active
    and g.is_active
    and g.status = 'published'
    and g.start_position is not null
    and g.finish_position is not null
    and cardinality(g.setup_steps) >= 3
    and cardinality(g.execution_steps) >= 3
    and cardinality(g.coaching_cues) >= 3
    and cardinality(g.common_mistakes) >= 3
    and cardinality(g.safety_notes) >= 2
    and g.breathing is not null
    and g.tempo_guidance is not null
    and jsonb_array_length(g.muscle_highlights) >= 1;

  if complete_guides <> active_exercises then
    raise exception 'Expected all % active exercises to have complete guides, found %', active_exercises, complete_guides;
  end if;
end
$validation$;

commit;
